/***************************************************************
 * PORTALSCHEDULERBRIDGE.GS - FAST + PROGRESS v3.0
 * Call Tracker -> Interview Portal secure bridge
 *
 * Install in the CALL TRACKER Apps Script project.
 *
 * This file exposes ONLY a small command allow-list through doPost().
 * Requests must include the long secret generated by:
 *
 *   setupPortalSchedulerBridgeSecret
 *
 * Supported commands:
 * - state
 * - setLeave
 * - extractToday
 * - autoAssign
 * - assignNew
 * - reassignOptions
 * - reassign
 *
 * IMPORTANT:
 * - Deploy this CALL TRACKER script as a separate Web App.
 * - Execute as: Me
 * - Access: Anyone
 * - Keep the /exec URL and secret only in the private portal project.
 ***************************************************************/

const CSB_CONFIG = {
  SPREADSHEET_ID:
    "1BD_XIhQW6d4w4dnrcM17wYgv6hZqdx7mTsAIYgUOC7M",

  MAIN_SHEET:
    "InterviewBot 2026",

  SECRET_PROPERTY:
    "PORTAL_SCHEDULER_BRIDGE_SECRET",

  TIME_ZONE:
    "Asia/Kolkata"
};


/***************************************************************
 * SETUP - RUN MANUALLY ONCE
 ***************************************************************/
function setupPortalSchedulerBridgeSecret(){

  const secret =
    Utilities.getUuid().replace(/-/g,"") +
    Utilities.getUuid().replace(/-/g,"") +
    Utilities.getUuid().replace(/-/g,"");

  PropertiesService
    .getScriptProperties()
    .setProperty(
      CSB_CONFIG.SECRET_PROPERTY,
      secret
    );

  Logger.log("PORTAL SCHEDULER BRIDGE SECRET:");
  Logger.log(secret);

  try{
    SpreadsheetApp.getUi().alert(
      "Portal Scheduler Bridge Secret\n\n" +
      secret +
      "\n\nCopy this value now. You will paste it into " +
      "the Interview Portal Control project."
    );
  }catch(err){
    // Web-app context has no UI. Manual editor runs do.
  }

  return secret;
}


/**
 * Optional manual rotation if you ever believe the secret was exposed.
 * After rotating, configure the portal project again.
 */
function rotatePortalSchedulerBridgeSecret(){
  return setupPortalSchedulerBridgeSecret();
}


/***************************************************************
 * WEB APP ENTRY POINT
 ***************************************************************/
function doGet(){
  return CSB_json_({
    ok: true,
    service: "Call Scheduler Bridge",
    message: "Bridge is online. POST authentication is required."
  });
}


function doPost(e){

  try{

    const body =
      JSON.parse(
        e && e.postData && e.postData.contents
          ? e.postData.contents
          : "{}"
      );

    CSB_requireSecret_(body.secret);

    const command =
      String(body.command || "").trim();

    const payload =
      body.payload && typeof body.payload === "object"
        ? body.payload
        : {};

    let data;

    switch(command){

      case "state":
        data = CSB_getState_();
        break;

      case "setLeave":
        data = CSB_setLeave_(payload.onLeave);
        break;

      case "extractToday":
        data = CSB_extractToday_(
          payload.operationId
        );
        break;

      case "autoAssign":
        data = CSB_autoAssign_(
          payload.operationId
        );
        break;

      case "assignNew":
        data = CSB_assignNew_(
          payload.operationId
        );
        break;

      case "progress":
        data = CSB_getOperationProgress_(
          payload.operationId
        );
        break;

      case "reassignOptions":
        data = CSB_reassignOptions_(payload.sourceRow);
        break;

      case "reassign":
        data = CSB_reassign_(
          payload.sourceRow,
          payload.handler
        );
        break;

      default:
        throw new Error("BRIDGE_COMMAND_NOT_ALLOWED");
    }

    return CSB_json_({
      ok: true,
      command: command,
      requestId: String(body.requestId || ""),
      data: data
    });

  }
  catch(err){

    Logger.log(
      "Portal Scheduler Bridge Error: " +
      (err && err.stack ? err.stack : err)
    );

    return CSB_json_({
      ok: false,
      error:
        err && err.message
          ? err.message
          : String(err)
    });
  }
}


/***************************************************************
 * AUTH
 ***************************************************************/
function CSB_requireSecret_(provided){

  const expected =
    String(
      PropertiesService
        .getScriptProperties()
        .getProperty(
          CSB_CONFIG.SECRET_PROPERTY
        ) || ""
    );

  if(!expected){
    throw new Error("BRIDGE_SECRET_NOT_CONFIGURED");
  }

  const actual =
    String(provided || "");

  if(
    actual.length !== expected.length ||
    actual !== expected
  ){
    throw new Error("BRIDGE_AUTH_FAILED");
  }
}


/***************************************************************
 * WORKBOOK HELPERS
 *
 * Web Apps do not have an active spreadsheet UI context, so the
 * bridge always opens the Call Tracker explicitly by ID.
 ***************************************************************/
function CSB_workbook_(){
  return SpreadsheetApp.openById(
    CSB_CONFIG.SPREADSHEET_ID
  );
}


function CSB_mainSheet_(){

  const sheet =
    CSB_workbook_()
      .getSheetByName(
        CSB_CONFIG.MAIN_SHEET
      );

  if(!sheet){
    throw new Error("CALL_TRACKER_MAIN_SHEET_NOT_FOUND");
  }

  return sheet;
}



/***************************************************************
 * OPERATION PROGRESS
 *
 * Uses Script Cache so a second bridge request can read the
 * stage while a long scheduler operation is still executing.
 ***************************************************************/
const CSB_PROGRESS_PREFIX =
  "CSB_OPERATION_PROGRESS_";


function CSB_setProgress_(
  operationId,
  percent,
  stage,
  detail,
  status,
  extra
){

  const id =
    String(operationId || "")
      .trim();

  if(!id){
    return;
  }

  const value = {
    operationId: id,
    percent: Math.max(
      0,
      Math.min(
        100,
        Number(percent || 0)
      )
    ),
    stage: String(stage || ""),
    detail: String(detail || ""),
    status: String(status || "Running"),
    updatedAt: new Date().toISOString()
  };

  if(
    extra &&
    typeof extra === "object"
  ){
    Object.keys(extra)
      .forEach(function(key){
        value[key] = extra[key];
      });
  }

  CacheService
    .getScriptCache()
    .put(
      CSB_PROGRESS_PREFIX + id,
      JSON.stringify(value),
      21600
    );
}


function CSB_getOperationProgress_(
  operationId
){

  const id =
    String(operationId || "")
      .trim();

  if(!id){
    return {
      operationId: "",
      percent: 0,
      stage: "Waiting",
      detail: "",
      status: "Waiting"
    };
  }

  const raw =
    CacheService
      .getScriptCache()
      .get(
        CSB_PROGRESS_PREFIX + id
      );

  if(!raw){
    return {
      operationId: id,
      percent: 0,
      stage: "Waiting",
      detail: "",
      status: "Waiting"
    };
  }

  try{
    return JSON.parse(raw);
  }catch(error){
    return {
      operationId: id,
      percent: 0,
      stage: "Waiting",
      detail: "",
      status: "Waiting"
    };
  }
}


/***************************************************************
 * BATCH READ HANDLER COLUMN
 ***************************************************************/
function CSB_handlerSnapshot_(
  sheet
){

  const lastRow =
    Math.max(
      1,
      sheet.getLastRow()
    );

  const values =
    sheet
      .getRange(
        1,
        COL.HANDLER,
        lastRow,
        1
      )
      .getDisplayValues();

  return {
    valueAt:
      function(rowNumber){

        const index =
          Number(rowNumber || 0) - 1;

        if(
          index < 0 ||
          index >= values.length
        ){
          return "";
        }

        return String(
          values[index][0] || ""
        )
        .replace(/\s+/g," ")
        .trim();
      }
  };
}


/***************************************************************
 * GROUP MATCHES INTO CONTIGUOUS WRITE BLOCKS
 ***************************************************************/
function CSB_matchWriteGroups_(
  matches
){

  const byRow = {};

  (matches || [])
    .forEach(function(match){

      const row =
        Number(
          match && match.lookupRow
            ? match.lookupRow
            : 0
        );

      if(row > 0){
        byRow[row] = match;
      }

    });

  const ordered =
    Object.keys(byRow)
      .map(Number)
      .sort(function(a,b){
        return a - b;
      });

  const groups = [];
  let current = null;

  ordered.forEach(function(row){

    if(
      !current ||
      row !== current.endRow + 1
    ){
      current = {
        startRow: row,
        endRow: row,
        matches: [byRow[row]]
      };
      groups.push(current);
      return;
    }

    current.endRow = row;
    current.matches.push(
      byRow[row]
    );

  });

  return groups;
}



/***************************************************************
 * STATE
 ***************************************************************/
function CSB_getState_(){

  const started =
    Date.now();

  const sheet =
    CSB_mainSheet_();

  const interviews =
    getExtractedInterviewObjects();

  const handlerSnapshot =
    CSB_handlerSnapshot_(
      sheet
    );

  let assigned = 0;
  let unassigned = 0;
  let support = 0;

  interviews.forEach(function(interview){

    const handler =
      handlerSnapshot
        .valueAt(
          interview.row
        );

    if(handler){
      assigned++;
    }else{
      unassigned++;
    }

    if(handler === SUPPORT_HANDLER){
      support++;
    }
  });

  const leaveConfig =
    getTodayLeaveConfig_();

  const handlers =
    getLeaveEligibleHandlers_();

  const nightCounts =
    getWeeklyNightCounts_();

  return {
    workingDate: getTodayDate(),
    workingDateKey:
      CSB_dateKeyFromHeader_(
        getTodayDate()
      ),

    leaveConfigured:
      leaveConfig !== null,

    onLeave:
      leaveConfig
        ? leaveConfig.onLeave.slice()
        : [],

    leaveEligibleHandlers:
      handlers,

    weeklyNightCounts:
      nightCounts,

    nightStarts:
      "2:00 AM",

    extracted:
      interviews.length,

    assigned:
      assigned,

    unassigned:
      unassigned,

    support:
      support,

    elapsedMs:
      Date.now() -
      started
  };
}


/***************************************************************
 * LEAVE
 ***************************************************************/
function CSB_setLeave_(onLeave){

  const eligible =
    getLeaveEligibleHandlers_();

  const requested =
    Array.isArray(onLeave)
      ? onLeave
      : [];

  const clean = [];
  const seen = {};

  requested.forEach(function(value){

    const wanted =
      String(value || "").trim();

    const actual =
      eligible.find(function(handler){
        return handler.toLowerCase() ===
          wanted.toLowerCase();
      });

    if(!actual){
      throw new Error(
        "INVALID_LEAVE_HANDLER: " + wanted
      );
    }

    if(!seen[actual]){
      seen[actual] = true;
      clean.push(actual);
    }
  });

  const config = {
    configured: true,
    date: getTodayDate(),
    onLeave: clean,
    configuredAt: new Date().toISOString(),
    source: "Interview Portal"
  };

  PropertiesService
    .getScriptProperties()
    .setProperty(
      getTodayLeavePropertyKey_(),
      JSON.stringify(config)
    );

  return {
    workingDate: config.date,
    configured: true,
    onLeave: clean
  };
}


/***************************************************************
 * EXTRACT TODAY - NO UI / NO TOAST
 *
 * Uses the existing matcher but performs the sheet writes here
 * because the original writeMatchesToSheet() uses UI-active methods.
 ***************************************************************/
function CSB_extractToday_(
  operationId
){

  const started =
    Date.now();

  CSB_setProgress_(
    operationId,
    5,
    "Starting extraction",
    "Waiting for the Call Tracker operation lock.",
    "Running"
  );

  const lock =
    LockService.getScriptLock();

  lock.waitLock(30000);

  try{

    CSB_setProgress_(
      operationId,
      15,
      "Preparing matcher",
      "Loading the active Call Tracker date block.",
      "Running"
    );

    const sheet =
      CSB_mainSheet_();

    CSB_setProgress_(
      operationId,
      25,
      "Matching interviews",
      "Running the existing Call Tracker matcher.",
      "Running"
    );

    const matches =
      buildMatches();

    CSB_setProgress_(
      operationId,
      65,
      "Matches prepared",
      matches.length +
      " row match result(s) prepared. Writing Column E in batches.",
      "Running",
      {
        total:
          matches.length
      }
    );

    const groups =
      CSB_matchWriteGroups_(
        matches
      );

    let updated = 0;
    let rejected = 0;
    let processed = 0;

    groups.forEach(
      function(group,index){

        const values = [];
        const backgrounds = [];

        group.matches
          .forEach(function(match){

            const valid =
              Boolean(
                match.interview &&
                Number(match.score || 0) >= 80
              );

            if(valid){

              values.push([
                match.interview.raw
              ]);

              backgrounds.push([
                COLORS.MATCH_FOUND
              ]);

              updated++;

            }else{

              values.push([
                ""
              ]);

              backgrounds.push([
                COLORS.MATCH_NOT_FOUND
              ]);

              rejected++;

            }

            processed++;

          });

        const range =
          sheet.getRange(
            group.startRow,
            COL.EXTRACTED,
            group.matches.length,
            1
          );

        range.setValues(
          values
        );

        range.setBackgrounds(
          backgrounds
        );

        const writePercent =
          groups.length
            ? (
                65 +
                Math.round(
                  (
                    (index + 1) /
                    groups.length
                  ) * 25
                )
              )
            : 90;

        CSB_setProgress_(
          operationId,
          Math.min(90,writePercent),
          "Writing extraction results",
          processed +
          " / " +
          matches.length +
          " match result(s) written.",
          "Running",
          {
            processed:
              processed,
            total:
              matches.length,
            matched:
              updated,
            unmatched:
              rejected
          }
        );

      }
    );

    SpreadsheetApp.flush();

    const result = {
      workingDate: getTodayDate(),
      matched: updated,
      unmatched: rejected,
      total:
        matches.length,
      writeGroups:
        groups.length,
      elapsedMs:
        Date.now() -
        started
    };

    CSB_setProgress_(
      operationId,
      100,
      "Extraction complete",
      "Matched " +
      updated +
      ", unmatched " +
      rejected +
      ".",
      "Completed",
      result
    );

    return result;

  }
  catch(error){

    CSB_setProgress_(
      operationId,
      100,
      "Extraction failed",
      error && error.message
        ? error.message
        : String(error),
      "Failed"
    );

    throw error;

  }
  finally{
    lock.releaseLock();
  }
}


/***************************************************************
 * INITIAL AUTO ASSIGN
 *
 * Safety rule:
 * If ANY extracted row already has Column F populated, the bridge
 * refuses the initial auto-assign. Use Assign New Interviews instead.
 ***************************************************************/
function CSB_autoAssign_(
  operationId
){

  const started =
    Date.now();

  CSB_setProgress_(
    operationId,
    5,
    "Starting initial assignment",
    "Validating Today's Leave.",
    "Running"
  );

  if(!isTodayLeaveConfigured_()){

    CSB_setProgress_(
      operationId,
      100,
      "Initial assignment blocked",
      "Set Today's Leave first.",
      "Failed"
    );

    throw new Error(
      "SET_TODAYS_LEAVE_FIRST"
    );
  }

  const lock =
    LockService.getScriptLock();

  lock.waitLock(30000);

  try{

    const sheet =
      CSB_mainSheet_();

    CSB_setProgress_(
      operationId,
      20,
      "Loading extracted interviews",
      "Checking existing assignments in one Column F read.",
      "Running"
    );

    const interviews =
      getExtractedInterviewObjects();

    const before =
      CSB_handlerSnapshot_(
        sheet
      );

    const existing =
      interviews.filter(
        function(interview){

          return before
            .valueAt(
              interview.row
            ) !== "";

        }
      );

    if(existing.length){

      CSB_setProgress_(
        operationId,
        100,
        "Initial assignment blocked",
        existing.length +
        " extracted call(s) already have an assignment. Use Assign New Interviews.",
        "Failed",
        {
          existing:
            existing.length,
          total:
            interviews.length
        }
      );

      throw new Error(
        "INITIAL_AUTO_ASSIGN_BLOCKED_EXISTING_ASSIGNMENTS_USE_ASSIGN_NEW"
      );
    }

    CSB_setProgress_(
      operationId,
      40,
      "Running assignment engine",
      "Executing the existing scheduler assignment rules.",
      "Running",
      {
        total:
          interviews.length
      }
    );

    autoAssignHandlers();

    CSB_setProgress_(
      operationId,
      85,
      "Checking assignments",
      "Reading final Column F assignments in one batch.",
      "Running"
    );

    const after =
      CSB_handlerSnapshot_(
        sheet
      );

    const assigned =
      interviews.filter(
        function(interview){

          return after
            .valueAt(
              interview.row
            ) !== "";

        }
      ).length;

    const result = {
      workingDate:
        getTodayDate(),
      assigned:
        assigned,
      total:
        interviews.length,
      elapsedMs:
        Date.now() -
        started
    };

    CSB_setProgress_(
      operationId,
      100,
      "Initial assignment complete",
      assigned +
      " / " +
      interviews.length +
      " call(s) assigned.",
      "Completed",
      result
    );

    return result;

  }
  catch(error){

    const current =
      CSB_getOperationProgress_(
        operationId
      );

    if(
      current.status !==
        "Failed"
    ){
      CSB_setProgress_(
        operationId,
        100,
        "Initial assignment failed",
        error && error.message
          ? error.message
          : String(error),
        "Failed"
      );
    }

    throw error;

  }
  finally{
    lock.releaseLock();
  }
}


/***************************************************************
 * ASSIGN NEW INTERVIEWS
 ***************************************************************/
function CSB_assignNew_(
  operationId
){

  const started =
    Date.now();

  CSB_setProgress_(
    operationId,
    5,
    "Starting incremental assignment",
    "Validating Today's Leave.",
    "Running"
  );

  if(!isTodayLeaveConfigured_()){

    CSB_setProgress_(
      operationId,
      100,
      "Incremental assignment blocked",
      "Set Today's Leave first.",
      "Failed"
    );

    throw new Error(
      "SET_TODAYS_LEAVE_FIRST"
    );
  }

  try{

    CSB_setProgress_(
      operationId,
      30,
      "Assigning new interviews",
      "Running the existing incremental assignment engine. Existing assignments stay locked.",
      "Running"
    );

    // Existing engine owns its ScriptLock.
    const result =
      assignNewInterviewsOnly();

    const output =
      result &&
      typeof result === "object"
        ? Object.assign(
            {},
            result,
            {
              elapsedMs:
                Date.now() -
                started
            }
          )
        : {
            assigned: 0,
            unassigned: 0,
            elapsedMs:
              Date.now() -
              started
          };

    CSB_setProgress_(
      operationId,
      100,
      "New-interview assignment complete",
      Number(output.assigned || 0) +
      " assigned; " +
      Number(output.unassigned || 0) +
      " still unassigned.",
      "Completed",
      output
    );

    return output;

  }
  catch(error){

    CSB_setProgress_(
      operationId,
      100,
      "New-interview assignment failed",
      error && error.message
        ? error.message
        : String(error),
      "Failed"
    );

    throw error;

  }
}


/***************************************************************
 * REASSIGNMENT
 ***************************************************************/
function CSB_reassignOptions_(sourceRow){

  const context =
    CSB_buildReassignmentContext_(
      sourceRow
    );

  const target =
    context.target;

  const scheduler =
    context.scheduler;

  const current =
    context.currentHandler;

  const suggested =
    findBestAvailableHandler(
      target,
      scheduler
    );

  const options = [];

  function addOption(name){

    if(
      !name ||
      name === current ||
      options.indexOf(name) !== -1
    ){
      return;
    }

    options.push(name);
  }

  addOption(suggested);

  MAIN_HANDLERS.forEach(function(handler){

    if(handler === current){
      return;
    }

    if(
      schedulerIsHandlerAvailable_(
        scheduler.availability,
        handler,
        target.interviewTime,
        target.duration
      )
    ){
      addOption(handler);
    }
  });

  if(
    SPECIAL_HANDLER !== current &&
    schedulerIsHandlerAvailable_(
      scheduler.availability,
      SPECIAL_HANDLER,
      target.interviewTime,
      target.duration
    )
  ){
    addOption(SPECIAL_HANDLER);
  }

  // Support is always an allowed final manual fallback.
  if(SUPPORT_HANDLER !== current){
    addOption(SUPPORT_HANDLER);
  }

  return {
    workingDate: getTodayDate(),
    sourceRow: target.row,
    candidate: target.candidate,
    time: target.interviewTime,
    duration: target.duration,
    currentHandler: current,
    suggestedHandler: suggested,
    options: options
  };
}


function CSB_reassign_(
  sourceRow,
  requestedHandler
){

  if(!isTodayLeaveConfigured_()){
    throw new Error("SET_TODAYS_LEAVE_FIRST");
  }

  const lock =
    LockService.getScriptLock();

  lock.waitLock(30000);

  try{

    const options =
      CSB_reassignOptions_(
        sourceRow
      );

    const requested =
      String(
        requestedHandler || ""
      )
      .trim();

    const actual =
      options.options.find(
        function(handler){
          return handler.toLowerCase() ===
            requested.toLowerCase();
        }
      );

    if(!actual){
      throw new Error(
        "REQUESTED_HANDLER_NOT_AVAILABLE"
      );
    }

    const sheet =
      CSB_mainSheet_();

    const cell =
      sheet.getRange(
        Number(sourceRow),
        COL.HANDLER
      );

    const oldHandler =
      String(
        cell.getDisplayValue() || ""
      )
      .trim();

    // Re-check that nobody changed the row while options were open.
    if(oldHandler !== options.currentHandler){
      throw new Error(
        "ASSIGNMENT_CHANGED_REFRESH_AND_TRY_AGAIN"
      );
    }

    cell.setValue(actual);

    return {
      workingDate: getTodayDate(),
      sourceRow: Number(sourceRow),
      candidate: options.candidate,
      oldHandler: oldHandler,
      newHandler: actual
    };

  }
  finally{
    lock.releaseLock();
  }
}


/**
 * Builds current-day availability while treating all existing
 * assignments EXCEPT the target row as locked reservations.
 */
function CSB_buildReassignmentContext_(
  sourceRow
){

  const row =
    Number(sourceRow || 0);

  if(!row){
    throw new Error("INVALID_SOURCE_ROW");
  }

  const sheet =
    CSB_mainSheet_();

  const interviews =
    getExtractedInterviewObjects();

  const target =
    interviews.find(function(item){
      return Number(item.row) === row;
    });

  if(!target){
    throw new Error(
      "CALL_NOT_FOUND_IN_LATEST_WORKING_DATE"
    );
  }

  const currentHandler =
    String(
      sheet
        .getRange(
          row,
          COL.HANDLER
        )
        .getDisplayValue() || ""
    )
    .trim();

  if(!currentHandler){
    throw new Error(
      "CALL_IS_CURRENTLY_UNASSIGNED"
    );
  }

  const scheduler = {
    interviews: interviews,
    availability:
      CSB_buildBaseAvailability_(),
    statistics: {},
    weeklyNightStatistics:
      getWeeklyNightCounts_(),
    assignments: [],
    unassigned: [],
    priority:
      MAIN_HANDLERS.slice()
  };

  MAIN_HANDLERS
    .concat([
      SPECIAL_HANDLER,
      SUPPORT_HANDLER
    ])
    .forEach(function(handler){
      scheduler.statistics[handler] = 0;
    });

  interviews.forEach(function(interview){

    if(Number(interview.row) === row){
      return;
    }

    const handler =
      String(
        sheet
          .getRange(
            interview.row,
            COL.HANDLER
          )
          .getDisplayValue() || ""
      )
      .trim();

    if(!handler){
      return;
    }

    if(
      handler !== SUPPORT_HANDLER &&
      (
        MAIN_HANDLERS.indexOf(handler) !== -1 ||
        handler === SPECIAL_HANDLER
      )
    ){

      schedulerReserveHandler_(
        scheduler.availability,
        handler,
        interview.interviewTime,
        interview.duration,
        "Existing Interview",
        interview.candidate
      );
    }

    scheduler.statistics[handler] =
      (scheduler.statistics[handler] || 0) + 1;

    recordNightAssignment_(
      scheduler,
      handler,
      interview
    );
  });

  return {
    target: target,
    currentHandler: currentHandler,
    scheduler: scheduler
  };
}


/***************************************************************
 * BASE AVAILABILITY
 *
 * Avoids UI-active Spreadsheet methods while running as Web App.
 ***************************************************************/
function CSB_buildBaseAvailability_(){

  const availability = {};

  MAIN_HANDLERS.forEach(function(handler){
    availability[handler] = [];
  });

  availability[SPECIAL_HANDLER] = [];
  availability[SUPPORT_HANDLER] = [];

  const busy =
    CSB_workbook_()
      .getSheetByName(
        SHEETS.BUSY
      );

  if(busy && busy.getLastRow() > 1){

    const rows =
      busy
        .getRange(
          2,
          1,
          busy.getLastRow() - 1,
          Math.min(
            6,
            busy.getLastColumn()
          )
        )
        .getValues();

    rows.forEach(function(row){

      const handler =
        String(row[0] || "").trim();

      const start =
        CSB_timeToMinutes_(
          row[1]
        );

      const duration =
        Number(row[2] || 0);

      if(
        !handler ||
        start < 0 ||
        duration <= 0
      ){
        return;
      }

      if(!availability[handler]){
        availability[handler] = [];
      }

      availability[handler].push({
        start: start,
        end: start + duration,
        duration: duration,
        source: "BusySlots"
      });
    });
  }

  // Apply leave from the SAME Call Tracker project Script Properties.
  getTodayOnLeaveHandlers_()
    .forEach(function(handler){

      if(!availability[handler]){
        availability[handler] = [];
      }

      availability[handler].push({
        start: 0,
        end: 2880,
        duration: 2880,
        source: "Leave",
        candidate: "ON LEAVE"
      });
    });

  return availability;
}


function CSB_timeToMinutes_(value){

  if(
    typeof schedulerTimelineMinutes_ ===
      "function"
  ){
    return schedulerTimelineMinutes_(
      value
    );
  }

  const text =
    String(value || "")
      .trim()
      .toUpperCase();

  const m =
    text.match(
      /(\d{1,2})[:.](\d{2})\s*(AM|PM)/
    );

  if(!m){
    return -1;
  }

  let h = Number(m[1]);
  const minute = Number(m[2]);
  const ap = m[3];

  if(ap === "PM" && h !== 12){
    h += 12;
  }

  if(ap === "AM" && h === 12){
    h = 0;
  }

  let total =
    h * 60 + minute;

  if(total < 360){
    total += 1440;
  }

  return total;
}


function CSB_dateKeyFromHeader_(text){

  const m =
    String(text || "")
      .match(
        /(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/
      );

  if(!m){
    return "";
  }

  return (
    m[3] + "-" +
    ("0" + m[1]).slice(-2) + "-" +
    ("0" + m[2]).slice(-2)
  );
}


/***************************************************************
 * JSON RESPONSE
 ***************************************************************/
function CSB_json_(obj){

  return ContentService
    .createTextOutput(
      JSON.stringify(obj)
    )
    .setMimeType(
      ContentService.MimeType.JSON
    );
}
